370.script:
# PHASE 1 — CLARIFY
# "Start with array of zeros. Apply updates [start,end,inc]: add inc to all elements in [start,end].
#  Return the result. Right?"
# "n=5,updates=[[1,3,2],[2,4,3],[0,2,-2]]→[-2,0,3,5,3] ✓"

class _370_RangeAddition_Brute:
    def getModifiedArray(self,n,updates):
        result=[0]*n
        for s,e,inc in updates:
            for i in range(s,e+1): result[i]+=inc
        return result

class _370_RangeAddition:
    def getModifiedArray(self,n,updates):
        diff=[0]*(n+1)
        for s,e,inc in updates: diff[s]+=inc; diff[e+1]-=inc
        result=[]; prefix=0
        for v in diff[:n]: prefix+=v; result.append(prefix)
        return result

# Difference array: +inc at start, -inc at end+1. Prefix sum gives final values. O(n+k). Space O(n).
# Follow-up: 2D range additions — 2D difference array.
# Follow-up: Increment Submatrices by One (LC 2536) — 2D version of this.

1314.script:
# PHASE 1 — CLARIFY
# "answer[i][j] = sum of all elements in mat where |r-i|<=k and |c-j|<=k. Right?"
# "mat=[[1,2,3],[4,5,6],[7,8,9]],k=1→[[12,21,16],[27,45,33],[24,39,28]] ✓"

class _1314_MatrixBlockSum_Brute:
    def matrixBlockSum(self,mat,k):
        m,n=len(mat),len(mat[0])
        return [[sum(mat[r][c] for r in range(max(0,i-k),min(m,i+k+1))
                                for c in range(max(0,j-k),min(n,j+k+1)))
                 for j in range(n)] for i in range(m)]

class _1314_MatrixBlockSum:
    def matrixBlockSum(self,mat,k):
        m,n=len(mat),len(mat[0])
        p=[[0]*(n+1) for _ in range(m+1)]
        for r in range(m):
            for c in range(n): p[r+1][c+1]=mat[r][c]+p[r][c+1]+p[r+1][c]-p[r][c]
        def query(r1,c1,r2,c2): return p[r2+1][c2+1]-p[r1][c2+1]-p[r2+1][c1]+p[r1][c1]
        return [[query(max(0,i-k),max(0,j-k),min(m-1,i+k),min(n-1,j+k))
                 for j in range(n)] for i in range(m)]

# 2D prefix sum + range query. O(mn) preprocess, O(1) per query. Total O(mn).
# Follow-up: sliding window sum for k changing per cell — still O(mn) with 2D prefix.
# Follow-up: circular matrix block sum — handle wrap with modular prefix sums.

2536.script:
# PHASE 1 — CLARIFY
# "n×n matrix of zeros. queries[i]=[r1,c1,r2,c2]: increment each cell in that rectangle by 1.
#  Return result matrix. Right?"
# "n=3,queries=[[1,1,2,2],[0,0,1,1]]→[[1,1,0],[1,2,1],[0,1,1]] ✓"

class _2536_IncrementSubmatricesByOne_Brute:
    def rangeAddQueries(self,n,queries):
        mat=[[0]*n for _ in range(n)]
        for r1,c1,r2,c2 in queries:
            for r in range(r1,r2+1):
                for c in range(c1,c2+1): mat[r][c]+=1
        return mat

class _2536_IncrementSubmatricesByOne:
    def rangeAddQueries(self,n,queries):
        diff=[[0]*(n+1) for _ in range(n+1)]
        for r1,c1,r2,c2 in queries:
            diff[r1][c1]+=1; diff[r1][c2+1]-=1
            diff[r2+1][c1]-=1; diff[r2+1][c2+1]+=1
        result=[[0]*n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                diff[r][c]+=(diff[r-1][c] if r>0 else 0)+(diff[r][c-1] if c>0 else 0)-(diff[r-1][c-1] if r>0 and c>0 else 0)
                result[r][c]=diff[r][c]
        return result

# 2D difference array: +1 at corner, propagate with 2D prefix sum. O(n²+q). Space O(n²).
# Follow-up: Range Addition (LC 370) — 1D version of this.
# Follow-up: if queries are circles (not rectangles) — need different approach (polar coordinates).

1823.script:
# PHASE 1 — CLARIFY
# "n friends in a circle, count k each round, eliminate the k-th. Who's last? Right?"
# "n=5,k=2: eliminate 2,4,1,5→winner=3 ✓  n=6,k=5→winner=1 ✓"

class _1823_FindWinnerCircularGame_Brute:
    def findTheWinner(self,n,k):
        from collections import deque
        q=deque(range(1,n+1))
        while len(q)>1:
            for _ in range(k-1): q.append(q.popleft())
            q.popleft()
        return q[0]

class _1823_FindWinnerCircularGame:
    def findTheWinner(self,n,k):
        # Josephus problem: f(1,k)=0, f(n,k)=(f(n-1,k)+k)%n, answer=f(n,k)+1
        pos=0
        for i in range(2,n+1): pos=(pos+k)%i
        return pos+1

# Josephus formula: O(n) time, O(1) space — no queue needed.
# Follow-up: find the order of elimination — run the queue simulation and record each removed element.
# Follow-up: if k changes each round — must simulate, no closed-form.

2104.script:
# PHASE 1 — CLARIFY
# "Sum of (max-min) for all subarrays. Right?"
# "nums=[1,2,3]→4 (ranges: 0,1,2,1,1,0 → sum=4) ✓"

class _2104_SumOfSubarrayRanges_Brute:
    def subArrayRanges(self,nums):
        total=0
        for i in range(len(nums)):
            lo=hi=nums[i]
            for j in range(i,len(nums)):
                lo=min(lo,nums[j]); hi=max(hi,nums[j])
                total+=hi-lo
        return total

class _2104_SumOfSubarrayRanges:
    def subArrayRanges(self,nums):
        # sum_of_maximums - sum_of_minimums
        def sum_subarray_mins(arr):
            n=len(arr); stack=[]; total=0
            for i in range(n+1):
                while stack and (i==n or arr[stack[-1]]>=arr[i]):
                    mid=stack.pop()
                    left=stack[-1] if stack else -1
                    total+=arr[mid]*(i-mid)*(mid-left)
                stack.append(i)
            return total
        def sum_subarray_maxs(arr):
            n=len(arr); stack=[]; total=0
            for i in range(n+1):
                while stack and (i==n or arr[stack[-1]]<=arr[i]):
                    mid=stack.pop()
                    left=stack[-1] if stack else -1
                    total+=arr[mid]*(i-mid)*(mid-left)
                stack.append(i)
            return total
        return sum_subarray_maxs(nums)-sum_subarray_mins(nums)

# Contribution technique: sum(max) - sum(min). Each uses monotonic stack. O(n). Space O(n).
# Follow-up: Sum of Subarray Minimums (LC 907) — just the min part.
# Follow-up: if range is defined differently (e.g., max*min) — similar contribution approach.

