907.script:
# PHASE 1 — CLARIFY
# "Return sum of min(subarray) for all subarrays, mod 10^9+7. Right?"
# "arr=[3,1,2,4]→17 (mins: 3,1,1,1,1,2,2,4→sum=17) ✓"
class _907_SumOfSubarrayMinimums_Brute:
    def sumSubarrayMins(self,arr):
        MOD=10**9+7; total=0
        for i in range(len(arr)):
            mn=arr[i]
            for j in range(i,len(arr)):
                mn=min(mn,arr[j]); total+=mn
        return total%MOD
class _907_SumOfSubarrayMinimums:
    def sumSubarrayMins(self,arr):
        MOD=10**9+7; n=len(arr); stack=[]; total=0
        for i in range(n+1):
            while stack and (i==n or arr[stack[-1]]>=arr[i]):
                mid=stack.pop(); left=stack[-1] if stack else -1
                total+=arr[mid]*(i-mid)*(mid-left)
            stack.append(i)
        return total%MOD
# Contribution: each element is min for (mid-left)*(right-mid) subarrays. O(n). Space O(n).
# Follow-up: Sum of Subarray Maximums — same approach, flip comparison.
# Follow-up: Sum of Subarray Ranges (LC 2104) = sum_max - sum_min.

1438.script:
# PHASE 1 — CLARIFY
# "Find longest subarray where max-min <= limit. Right?"
# "nums=[8,2,4,7],limit=4→2 (subarray [2,4] or [4,7]) ✓"
class _1438_LongestContinuousSubarrayAbsDiff_Brute:
    def longestSubarray(self,nums,limit):
        best=0
        for i in range(len(nums)):
            mn=mx=nums[i]
            for j in range(i,len(nums)):
                mn=min(mn,nums[j]); mx=max(mx,nums[j])
                if mx-mn<=limit: best=max(best,j-i+1)
                else: break
        return best
class _1438_LongestContinuousSubarrayAbsDiff:
    def longestSubarray(self,nums,limit):
        from collections import deque
        max_d=deque(); min_d=deque(); left=0; best=0
        for right,n in enumerate(nums):
            while max_d and nums[max_d[-1]]<=n: max_d.pop()
            while min_d and nums[min_d[-1]]>=n: min_d.pop()
            max_d.append(right); min_d.append(right)
            while nums[max_d[0]]-nums[min_d[0]]>limit:
                left+=1
                if max_d[0]<left: max_d.popleft()
                if min_d[0]<left: min_d.popleft()
            best=max(best,right-left+1)
        return best
# Two monotonic deques (max and min) + sliding window. O(n). Space O(n).
# Follow-up: shortest such subarray — binary search + deque.
# Follow-up: if limit can change per query — offline processing with segment tree.

1673.script:
