class _1673_FindMostCompetitiveSubsequence_Brute:
    def mostCompetitive(self,nums,k):
        result=[]; n=len(nums)
        for i,v in enumerate(nums):
            while result and result[-1]>v and len(result)+n-i>k:
                result.pop()
            if len(result)<k: result.append(v)
        return result
class _1673_FindMostCompetitiveSubsequence:
    def mostCompetitive(self,nums,k):
        stack=[]; n=len(nums)
        for i,v in enumerate(nums):
            while stack and stack[-1]>v and len(stack)+n-i>k:
                stack.pop()
            if len(stack)<k: stack.append(v)
        return stack
# Monotonic increasing stack, keep exactly k. Same as brute — already O(n). Space O(k).
