# PHASE 1 — CLARIFY
# "Count subarrays where |nums[i]-nums[j]|<=2 for all pairs i,j in subarray. Right?"
# "nums=[5,4,2,4]→8 ✓"
class _2762_ContinuousSubarrays_Brute:
    def continuousSubarrays(self,nums):
        count=0
        for i in range(len(nums)):
            mn=mx=nums[i]
            for j in range(i,len(nums)):
                mn=min(mn,nums[j]); mx=max(mx,nums[j])
                if mx-mn<=2: count+=1
                else: break
        return count
class _2762_ContinuousSubarrays:
    def continuousSubarrays(self,nums):
        from collections import deque
        max_d=deque(); min_d=deque(); left=0; count=0
        for right,n in enumerate(nums):
            while max_d and nums[max_d[-1]]<=n: max_d.pop()
            while min_d and nums[min_d[-1]]>=n: min_d.pop()
            max_d.append(right); min_d.append(right)
            while nums[max_d[0]]-nums[min_d[0]]>2:
                left+=1
                if max_d[0]<left: max_d.popleft()
                if min_d[0]<left: min_d.popleft()
            count+=right-left+1
        return count
# Two deques + sliding window. count+=window_size at each step. O(n). Space O(n).
