47.script:
# PHASE 1 — CLARIFY
# "Return all unique permutations of nums which may contain duplicates. Right?"
# "nums=[1,1,2]→[[1,1,2],[1,2,1],[2,1,1]] ✓"
class _47_PermutationsII_Brute:
    def permuteUnique(self,nums):
        result=set(); used=[False]*len(nums); nums.sort()
        def bt(path):
            if len(path)==len(nums): result.add(tuple(path)); return
            for i in range(len(nums)):
                if used[i]: continue
                used[i]=True; bt(path+[nums[i]]); used[i]=False
        bt([]); return [list(t) for t in result]
class _47_PermutationsII:
    def permuteUnique(self,nums):
        nums.sort(); result=[]; used=[False]*len(nums)
        def bt(path):
            if len(path)==len(nums): result.append(path[:]); return
            for i in range(len(nums)):
                if used[i]: continue
                if i>0 and nums[i]==nums[i-1] and not used[i-1]: continue
                used[i]=True; path.append(nums[i]); bt(path); path.pop(); used[i]=False
        bt([]); return result
# Sort + skip duplicate at same level if previous same value unused. O(n!). Space O(n).
# Follow-up: count unique permutations without generating — n!/product(count_i!).
# Follow-up: next permutation (LC 31) — generate just the next one in O(n).

77.script:
# PHASE 1 — CLARIFY
# "Return all combinations of k numbers from range [1,n]. Right?"
# "n=4,k=2→[[1,2],[1,3],[1,4],[2,3],[2,4],[3,4]] ✓"
class _77_Combinations_Brute:
    def combine(self,n,k):
        from itertools import combinations
        return [list(c) for c in combinations(range(1,n+1),k)]
class _77_Combinations:
    def combine(self,n,k):
        result=[]
        def bt(start,path):
            if len(path)==k: result.append(path[:]); return
            for i in range(start,n+1-(k-len(path))+1):
                path.append(i); bt(i+1,path); path.pop()
        bt(1,[]); return result
# Pruning: upper bound = n-(k-len(path))+1 so enough elements remain. O(C(n,k)*k). Space O(k).
# Follow-up: Combination Sum (LC 39) — target sum, elements can repeat.
# Follow-up: count without generating — C(n,k) = n!/(k!(n-k)!).

216.script:
# PHASE 1 — CLARIFY
# "Find all combinations of exactly k numbers from 1-9 that sum to n. Each digit used at most once. Right?"
# "k=3,n=7→[[1,2,4]] ✓  k=3,n=9→[[1,2,6],[1,3,5],[2,3,4]] ✓"
class _216_CombinationSumIII_Brute:
    def combinationSum3(self,k,n):
        result=[]
        def bt(start,path,remaining):
            if len(path)==k and remaining==0: result.append(path[:]); return
            if len(path)==k or remaining<=0: return
            for i in range(start,10):
                if i>remaining: break
                path.append(i); bt(i+1,path,remaining-i); path.pop()
        bt(1,[],(n)); return result
class _216_CombinationSumIII:
    def combinationSum3(self,k,n):
        result=[]
        def bt(start:int,path:list,rem:int)->None:
            if len(path)==k:
                if rem==0: result.append(path[:])
                return
            for i in range(start,10):
                if i>rem: break
                path.append(i); bt(i+1,path,rem-i); path.pop()
        bt(1,[],n); return result
# Backtracking from 1-9, prune when digit > remaining. O(C(9,k)). Space O(k).
