109.script:
# PHASE 1 — CLARIFY
# "Convert sorted linked list to height-balanced BST. Right?"
# "head=[-10,-3,0,5,9]→[0,-3,9,-10,null,5] (height-balanced BST) ✓"
class _109_ConvertSortedListToBST_Brute:
    def sortedListToBST(self,head):
        vals=[]; curr=head
        while curr: vals.append(curr.val); curr=curr.next
        def build(lo,hi):
            if lo>hi: return None
            mid=(lo+hi)//2; node=TreeNode(vals[mid])
            node.left=build(lo,mid-1); node.right=build(mid+1,hi)
            return node
        return build(0,len(vals)-1)
class _109_ConvertSortedListToBST:
    def sortedListToBST(self,head):
        def find_mid(lo,hi):
            slow=fast=lo
            while fast!=hi and fast.next!=hi:
                slow=slow.next; fast=fast.next.next
            return slow
        def build(lo,hi):
            if lo==hi: return None
            mid=find_mid(lo,hi); node=TreeNode(mid.val)
            node.left=build(lo,mid); node.right=build(mid.next,hi)
            return node
        return build(head,None)
# Slow/fast to find middle in-place. O(n log n) — each level finds mid in O(n/level).
# Better: inorder simulation O(n) by advancing list pointer in BST inorder.
# Follow-up: Convert Sorted Array to BST (LC 108) — same but O(n) with array indexing.

1985.script:
# PHASE 1 — CLARIFY
# "Strings representing integers. Find kth largest. Compare by value (length first, then lex). Right?"
# "nums=['3','6','7','10'],k=4→'3' ✓  nums=['2','21','12','1'],k=3→'2' ✓"
class _1985_FindKthLargestIntegerArray_Brute:
    def kthLargestNumber(self,nums,k):
        nums.sort(key=lambda x:(len(x),x),reverse=True)
        return nums[k-1]
class _1985_FindKthLargestIntegerArray:
    def kthLargestNumber(self,nums,k):
        import random
        def compare(a,b): return (len(a),a)<(len(b),b)
        def quickselect(lo,hi,k):
            if lo==hi: return nums[lo]
            pivot_idx=random.randint(lo,hi)
            nums[pivot_idx],nums[hi]=nums[hi],nums[pivot_idx]
            pivot=nums[hi]; store=lo
            for i in range(lo,hi):
                if compare(nums[i],pivot): nums[store],nums[i]=nums[i],nums[store]; store+=1
            nums[store],nums[hi]=nums[hi],nums[store]
            rank=hi-store+1  # rank from the right
            if rank==k: return nums[store]
            elif rank<k: return quickselect(lo,store-1,k-rank)
            else: return quickselect(store+1,hi,k)
        return quickselect(0,len(nums)-1,k)
# QuickSelect: O(n) avg, O(n²) worst. Key: compare by (length, lex) for numeric string comparison.
# Follow-up: if numbers can be negative — handle sign in comparison.
# Follow-up: Kth Largest Element in an Array (LC 215) — same QuickSelect on integers.

701.script:
# PHASE 1 — CLARIFY
# "Insert val into BST. Return root of modified tree. Right?"
# "root=[4,2,7,1,3],val=5→[4,2,7,1,3,5] ✓"
class _701_InsertIntoBST_Brute:
    def insertIntoBST(self,root,val):
        if not root: return TreeNode(val)
        if val<root.val: root.left=self.insertIntoBST(root.left,val)
        else: root.right=self.insertIntoBST(root.right,val)
        return root
class _701_InsertIntoBST:
    def insertIntoBST(self,root,val):
        node=TreeNode(val)
        if not root: return node
        curr=root
        while True:
            if val<curr.val:
                if not curr.left: curr.left=node; break
                curr=curr.left
            else:
                if not curr.right: curr.right=node; break
                curr=curr.right
        return root
# Iterative BST insert: O(h) time, O(1) space. Recursive: O(h) time, O(h) space.
# Follow-up: Delete Node in a BST (LC 450) — more complex, needs successor finding.
# Follow-up: if tree might become unbalanced — self-balancing BST (AVL/Red-Black).

