421.script:
# PHASE 1 — CLARIFY
# "Find the maximum XOR of any two numbers in nums. Right?"
# "nums=[3,10,5,25,2,8]→28 (5 XOR 25) ✓"
class _421_MaxXORTwoNumbers_Brute:
    def findMaximumXOR(self,nums):
        return max(a^b for i,a in enumerate(nums) for b in nums[i+1:])
class _421_MaxXORTwoNumbers:
    def findMaximumXOR(self,nums):
        # Trie-based: insert all, for each num find complement path
        class TrieNode:
            def __init__(self): self.children=[None,None]
        root=TrieNode()
        for n in nums:
            node=root
            for i in range(31,-1,-1):
                bit=(n>>i)&1
                if not node.children[bit]: node.children[bit]=TrieNode()
                node=node.children[bit]
        best=0
        for n in nums:
            node=root; curr_xor=0
            for i in range(31,-1,-1):
                bit=(n>>i)&1; want=1-bit
                if node.children[want]: curr_xor=(curr_xor<<1)|1; node=node.children[want]
                else: curr_xor=(curr_xor<<1); node=node.children[bit]
            best=max(best,curr_xor)
        return best
# Trie: greedily take the opposite bit. O(32n)=O(n). Space O(32n)=O(n).
# Alternative: bit-by-bit O(32n) using prefix sets.
# Follow-up: Maximum XOR With an Element From Array (LC 1707) — offline queries with sorted trie.

648.script:
# PHASE 1 — CLARIFY
# "Given dictionary of roots, replace each word in sentence with shortest root prefix. Right?"
# "dictionary=['cat','bat','rat'],sentence='the cattle was rattled by the battery':
#  →'the cat was rat by the bat' ✓"
class _648_ReplaceWords_Brute:
    def replaceWords(self,dictionary,sentence):
        roots=sorted(dictionary,key=len)
        words=sentence.split()
        def replace(w):
            for r in roots:
                if w.startswith(r): return r
            return w
        return ' '.join(replace(w) for w in words)
class _648_ReplaceWords:
    def replaceWords(self,dictionary,sentence):
        trie={}
        for root in dictionary:
            node=trie
            for ch in root: node=node.setdefault(ch,{})
            node['#']=True
        def find_root(word):
            node=trie
            for i,ch in enumerate(word):
                if ch not in node: break
                node=node[ch]
                if '#' in node: return word[:i+1]
            return word
        return ' '.join(find_root(w) for w in sentence.split())
# Trie: insert all roots, query each word. O(sum_root_len + n*avg_word_len). Space O(sum_root_len).
# Follow-up: if roots can be prefixes of each other — trie naturally handles (shortest match wins).
# Follow-up: Longest Word in Dictionary (LC 720) — similar trie traversal.

1405.script:
# PHASE 1 — CLARIFY
# "Build longest string using at most a 'a's, b 'b's, c 'c's with no 3 consecutive same chars. Right?"
# "a=1,b=1,c=7→'ccaccbcc' or similar, len=8 ✓"
class _1405_LongestHappyString_Brute:
    def longestDiverseString(self,a,b,c):
        import heapq
        heap=[(-a,'a'),(-b,'b'),(-c,'c')]
        heapq.heapify(heap); result=[]
        while heap:
            cnt,ch=heapq.heappop(heap)
            if result[-2:]==[ch,ch] if len(result)>=2 else False:
                if not heap: break
                cnt2,ch2=heapq.heappop(heap)
                result.append(ch2)
                if cnt2+1<0: heapq.heappush(heap,(cnt2+1,ch2))
                heapq.heappush(heap,(cnt,ch))
            else:
                result.append(ch)
                if cnt+1<0: heapq.heappush(heap,(cnt+1,ch))
        return ''.join(result)
class _1405_LongestHappyString:
    def longestDiverseString(self,a,b,c):
        import heapq
        heap=[]; 
        for cnt,ch in [(-a,'a'),(-b,'b'),(-c,'c')]:
            if cnt<0: heapq.heappush(heap,(cnt,ch))
        result=[]
        while heap:
            cnt,ch=heapq.heappop(heap)
            if len(result)>=2 and result[-1]==result[-2]==ch:
                if not heap: break
                cnt2,ch2=heapq.heappop(heap)
                result.append(ch2)
                if cnt2+1<0: heapq.heappush(heap,(cnt2+1,ch2))
                heapq.heappush(heap,(cnt,ch))
            else:
                result.append(ch); 
                if cnt+1<0: heapq.heappush(heap,(cnt+1,ch))
        return ''.join(result)
# Greedy: always pick most frequent char, unless it would create 3-in-a-row. O(n log 3)=O(n).
# Follow-up: Reorganize String (LC 767) — binary alphabet (any/none), same greedy.
# Follow-up: Task Scheduler (LC 621) — count result length without constructing.

1642.script:
# PHASE 1 — CLARIFY
# "Given heights, ladders, bricks: climb up requires bricks(diff) or one ladder (free).
#  Use ladders for biggest climbs. Return furthest building reachable. Right?"
# "heights=[4,2,7,6,9,14,12],ladders=1,bricks=5→4 ✓"
class _1642_FurthestBuildingYouCanReach_Brute:
    def furthestBuilding(self,heights,bricks,ladders):
        import heapq; climbs=[]
        for i in range(len(heights)-1):
            d=heights[i+1]-heights[i]
            if d>0:
                heapq.heappush(climbs,d)
                if len(climbs)>ladders:
                    bricks-=heapq.heappop(climbs)
                if bricks<0: return i
        return len(heights)-1
class _1642_FurthestBuildingYouCanReach:
    def furthestBuilding(self,heights,bricks,ladders):
        import heapq
        min_heap=[]  # track ladder-used climbs (min-heap)
        for i in range(len(heights)-1):
            d=heights[i+1]-heights[i]
            if d<=0: continue
            heapq.heappush(min_heap,d)
            if len(min_heap)>ladders:
                bricks-=heapq.heappop(min_heap)
            if bricks<0: return i
        return len(heights)-1
# Greedily assign ladders to largest climbs (min-heap swaps smallest ladder-climb to bricks). O(n log L).
# Follow-up: if we can also use ropes of varying lengths — extend the heap with rope constraints.
# Follow-up: return the path taken (which resource used where) — track assignments.

