378.script:
# PHASE 1 — CLARIFY
# "n×n matrix, each row and column sorted. Find kth smallest. Right?"
# "matrix=[[1,5,9],[10,11,13],[12,13,15]],k=8→13 ✓"
class _378_KthSmallestSortedMatrix_Brute:
    def kthSmallest(self,matrix,k):
        import heapq
        n=len(matrix)
