class _3578_CountPartitionsMaxMinDiffAtMostK_Brute:
    def countPartitions(self,nums,k):
        MOD=10**9+7; n=len(nums); dp=[0]*(n+1); dp[0]=1
        for i in range(1,n+1):
            mn=mx=nums[i-1]
            for j in range(i-1,-1,-1):
                mn=min(mn,nums[j]); mx=max(mx,nums[j])
                if mx-mn<=k: dp[i]=(dp[i]+dp[j])%MOD
                else: break
        return dp[n]
