    def countPartitions(self,nums,k):
        from collections import deque
        MOD=10**9+7; n=len(nums)
        dp=[0]*(n+1); dp[0]=1
        prefix=[0]*(n+1); prefix[0]=1
        max_d=deque(); min_d=deque(); left=0
        for right in range(n):
            while max_d and nums[max_d[-1]]<=nums[right]: max_d.pop()
            while min_d and nums[min_d[-1]]>=nums[right]: min_d.pop()
            max_d.append(right); min_d.append(right)
            while nums[max_d[0]]-nums[min_d[0]]>k:
                left+=1
                if max_d[0]<left: max_d.popleft()
                if min_d[0]<left: min_d.popleft()
            # dp[right+1] = sum(dp[left..right])
            dp[right+1]=(prefix[right+1]-prefix[left])%MOD
            prefix[right+2]=(prefix[right+1]+dp[right+1])%MOD
        return dp[n]
