            elif a>r:
                if not inserted: new.append((l,r)); inserted=True
                new.append((a,b))
            else: l=min(l,a); r=max(r,b)
        if not inserted: new.append((l,r))
        self.ranges=new
    def queryRange(self,l,r):
        return any(a<=l and r<=b for a,b in self.ranges)
    def removeRange(self,l,r):
        new=[]
        for a,b in self.ranges:
            if b<=l or a>=r: new.append((a,b))
            else:
                if a<l: new.append((a,l))
                if b>r: new.append((r,b))
        self.ranges=new
class _715_RangeModule:
    def __init__(self):
        import sortedcontainers
        self.sl=sortedcontainers.SortedList()  # list of (start, end) non-overlapping sorted by start
    def addRange(self,l,r):
        import bisect
        ranges=self.sl; i=ranges.bisect_left((l,)); j=ranges.bisect_right((r,))
        # Merge with overlapping/touching ranges
        if i>0 and ranges[i-1][1]>=l: i-=1
        if j<len(ranges) and ranges[j][0]<=r: j+=1
        if i<j: l=min(l,ranges[i][0]); r=max(r,ranges[j-1][1])
        # Remove merged, add new
        for _ in range(j-i): ranges.pop(i)
        ranges.add((l,r))
    def queryRange(self,l,r):
        idx=self.sl.bisect_right((l,))-1
        return idx>=0 and self.sl[idx][1]>=r
    def removeRange(self,l,r):
        new_left=new_right=None
        to_remove=[]; ranges=self.sl
        i=ranges.bisect_left((l,))
        if i>0 and ranges[i-1][1]>l: i-=1
        while i<len(ranges) and ranges[i][0]<r:
            a,b=ranges[i]
            if a<l: new_left=(a,l)
            if b>r: new_right=(r,b)
            to_remove.append((a,b)); i+=1
        for rng in to_remove: ranges.remove(rng)
        if new_left: ranges.add(new_left)
        if new_right: ranges.add(new_right)
