# PHASE 1 — CLARIFY
# "Count paths from 0 to n-1 with minimum total time. Return mod 10^9+7. Right?"
# "n=7,roads=[[0,6,7],[0,1,2],[1,2,3],[1,3,3],[6,3,3],[3,5,1],[6,5,1],[2,5,1],[0,4,5],[4,6,2]]→4 ✓"
class _1976_NumberOfWaysToArriveAtDestination_Brute:
    def countPaths(self,n,roads):
        import heapq; from collections import defaultdict; MOD=10**9+7
        g=defaultdict(list)
        for u,v,t in roads: g[u].append((v,t)); g[v].append((u,t))
        dist=[float('inf')]*n; dist[0]=0; ways=[0]*n; ways[0]=1
        heap=[(0,0)]
        while heap:
            d,u=heapq.heappop(heap)
            if d>dist[u]: continue
            for v,t in g[u]:
                if dist[u]+t<dist[v]: dist[v]=dist[u]+t; ways[v]=ways[u]; heapq.heappush(heap,(dist[v],v))
                elif dist[u]+t==dist[v]: ways[v]=(ways[v]+ways[u])%MOD
        return ways[n-1]
class _1976_NumberOfWaysToArriveAtDestination:
    def countPaths(self,n,roads):
        import heapq; from collections import defaultdict; MOD=10**9+7
        g=defaultdict(list)
        for u,v,t in roads: g[u].append((v,t)); g[v].append((u,t))
        dist=[float('inf')]*n; dist[0]=0; ways=[0]*n; ways[0]=1
        heap=[(0,0)]
