# PHASE 1 — CLARIFY
# "Assign n workers to m bikes (m>=n). Minimize total Manhattan distance. Right?"
# "workers=[[0,0],[1,1]],bikes=[[2,2],[1,3]]→4 ✓"
class _1066_CampusBikesII_Brute:
    def assignBikes(self,workers,bikes):
        from itertools import permutations
        n=len(workers); m=len(bikes); best=float('inf')
        for perm in permutations(range(m),n):
            cost=sum(abs(workers[i][0]-bikes[perm[i]][0])+abs(workers[i][1]-bikes[perm[i]][1]) for i in range(n))
            best=min(best,cost)
        return best
class _1066_CampusBikesII:
    def assignBikes(self,workers,bikes):
        from functools import lru_cache
        n=len(workers); m=len(bikes)
        @lru_cache(maxsize=None)
        def dp(w,mask):
            if w==n: return 0
            best=float('inf')
            for b in range(m):
                if mask&(1<<b): continue
                d=abs(workers[w][0]-bikes[b][0])+abs(workers[w][1]-bikes[b][1])
                best=min(best,d+dp(w+1,mask|(1<<b)))
