1986.script:
# PHASE 1 — CLARIFY
# "n tasks. Each session max sessionTime. Tasks can't be split. Min sessions to complete all. Right?"
# "tasks=[1,2,3],sessionTime=3→2 ✓ (sessions:[1,2],[3])"
class _1986_MinWorkSessions_Brute:
    def minSessions(self,tasks,sessionTime):
        from functools import lru_cache
        n=len(tasks); full=(1<<n)-1
        @lru_cache(maxsize=None)
        def dp(mask,remaining):
            if mask==full: return 0
            sessions=0; bits=full^mask
            # Try adding each unfinished task to current session
            i=0; result=float('inf')
            while bits:
                lsb=bits&(-bits); bit_idx=lsb.bit_length()-1
                if tasks[bit_idx]<=remaining:
                    result=min(result,dp(mask|lsb,remaining-tasks[bit_idx]))
                else: result=min(result,1+dp(mask|lsb,sessionTime-tasks[bit_idx]))
                bits^=lsb
            return result
        # Simpler: dp[mask]=min sessions with tasks in mask done
        dp2=[float('inf')]*(1<<n); dp2[0]=1
        time=[0]*(1<<n)  # time used in current session
        for mask in range(1<<n):
            for i in range(n):
                if mask&(1<<i): continue
                nmask=mask|(1<<i)
                if time[mask]+tasks[i]<=sessionTime:
                    if dp2[mask]<dp2[nmask] or (dp2[mask]==dp2[nmask] and time[mask]+tasks[i]<time[nmask]):
                        dp2[nmask]=dp2[mask]; time[nmask]=time[mask]+tasks[i]
                else:
                    if dp2[mask]+1<dp2[nmask] or (dp2[mask]+1==dp2[nmask] and tasks[i]<time[nmask]):
                        dp2[nmask]=dp2[mask]+1; time[nmask]=tasks[i]
        return dp2[full]
class _1986_MinWorkSessions:
    def minSessions(self,tasks,sessionTime):
        n=len(tasks); full=(1<<n)-1
        dp=[float('inf')]*(1<<n); dp[0]=0; rem=[0]*(1<<n); rem[0]=sessionTime
        for mask in range(full+1):
            if dp[mask]==float('inf'): continue
            for i in range(n):
                if mask>>i&1: continue
                nmask=mask|(1<<i)
                if tasks[i]<=rem[mask]:
                    if dp[mask]<dp[nmask] or (dp[mask]==dp[nmask] and rem[mask]-tasks[i]>rem[nmask]):
                        dp[nmask]=dp[mask]; rem[nmask]=rem[mask]-tasks[i]
                else:
                    if dp[mask]+1<dp[nmask]:
                        dp[nmask]=dp[mask]+1; rem[nmask]=sessionTime-tasks[i]
        return dp[full]
# Bitmask DP tracking sessions used and remaining time in current session. O(n*2^n). Space O(2^n).
# Follow-up: if sessions have different max times — parameterize rem per session type.
# Follow-up: if tasks have priorities — weighted DP with priority score.

