# PHASE 1 — CLARIFY
# "Distribute n cookie bags among k children to minimize the maximum sum any child receives. Right?"
# "cookies=[8,15,10,20,8],k=2→31 ✓"
class _2305_FairDistributionOfCookies_Brute:
    def distributeCookies(self,cookies,k):
        result=[float('inf')]
        def bt(idx,children):
            if idx==len(cookies): result[0]=min(result[0],max(children)); return
            for i in range(k):
                children[i]+=cookies[idx]
                bt(idx+1,children)
                children[i]-=cookies[idx]
                if children[i]==0: break  # prune symmetric branches
        bt(0,[0]*k); return result[0]
class _2305_FairDistributionOfCookies:
    def distributeCookies(self,cookies,k):
        n=len(cookies); subset_sum=[0]*(1<<n)
        for mask in range(1<<n):
            for i in range(n):
                if mask>>i&1: subset_sum[mask]+=cookies[i]
        dp=[[float('inf')]*(1<<n) for _ in range(k+1)]
        dp[0][0]=0
        for j in range(1,k+1):
            for mask in range(1<<n):
                sub=mask
                while sub:
                    dp[j][mask]=min(dp[j][mask],max(dp[j-1][mask^sub],subset_sum[sub]))
                    sub=(sub-1)&mask
        return dp[k][(1<<n)-1]
# Bitmask DP: assign subset of bags to each child. O(k*3^n) — each bit in 3 states. Space O(k*2^n).
# Follow-up: if children have capacity limits — add constraint check in DP.
# Follow-up: if we also care about variance (fairness beyond max) — different objective function.

688.script:
# PHASE 1 — CLARIFY
# "Knight starts at (r,c) on NxN board. After k moves, probability it's still on board. Right?"
# "n=3,k=2,row=0,col=0→0.0625 ✓"
class _688_KnightProbabilityInChessboard_Brute:
    def knightProbability(self,n,k,row,col):
        MOVES=[(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(r,c,moves):
            if not(0<=r<n and 0<=c<n): return 0
            if moves==0: return 1
            return sum(dp(r+dr,c+dc,moves-1) for dr,dc in MOVES)/8
        return dp(row,col,k)
class _688_KnightProbabilityInChessboard:
    def knightProbability(self,n,k,row,col):
        MOVES=[(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
        dp=[[0]*n for _ in range(n)]; dp[row][col]=1
        for _ in range(k):
            ndp=[[0]*n for _ in range(n)]
            for r in range(n):
                for c in range(n):
                    if dp[r][c]==0: continue
                    for dr,dc in MOVES:
                        nr,nc=r+dr,c+dc
                        if 0<=nr<n and 0<=nc<n: ndp[nr][nc]+=dp[r][c]/8
            dp=ndp
        return sum(dp[r][c] for r in range(n) for c in range(n))
# Forward DP spreading probability each step. O(k*n²). Space O(n²).
# Follow-up: Out of Boundary Paths (LC 576) — count paths leaving the grid (complement).
# Follow-up: if knight has a target square — track probability at that square specifically.

