# PHASE 1 — CLARIFY
# "Count primes strictly less than n. Right?"
# "n=10→4 (2,3,5,7) ✓"
class _204_CountPrimes_Brute:
    def countPrimes(self,n):
        if n<2: return 0
        sieve=[True]*n; sieve[0]=sieve[1]=False
        for i in range(2,int(n**0.5)+1):
            if sieve[i]:
                for j in range(i*i,n,i): sieve[j]=False
        return sum(sieve)
class _204_CountPrimes:
    def countPrimes(self,n):
        if n<2: return 0
        sieve=[True]*n; sieve[0]=sieve[1]=False
        i=2
        while i*i<n:
            if sieve[i]:
                j=i*i
                while j<n: sieve[j]=False; j+=i
            i+=1
        return sum(sieve)
# Sieve of Eratosthenes. O(n log log n). Space O(n).
# Follow-up: primes in range [a,b] efficiently — segmented sieve O(sqrt(b) + (b-a) log log b).
# Follow-up: nth prime — sieve up to n*ln(n) as upper bound estimate.

