# PHASE 1 — CLARIFY
# "Envelope A fits in B if A.w<B.w AND A.h<B.h. Find max nesting depth. Right?"
# "envelopes=[[5,4],[6,4],[6,7],[2,3]]→3 ✓ (2,3)→(5,4)→(6,7)"
class _354_RussianDollEnvelopes_Brute:
    def maxEnvelopes(self,envelopes):
        envelopes.sort(key=lambda x:(x[0],-x[1]))
        # LIS on heights
        import bisect
        tails=[]
        for _,h in envelopes:
            pos=bisect.bisect_left(tails,h)
            if pos==len(tails): tails.append(h)
            else: tails[pos]=h
        return len(tails)
class _354_RussianDollEnvelopes:
    def maxEnvelopes(self,envelopes):
        import bisect
        envelopes.sort(key=lambda x:(x[0],-x[1]))
        dp=[]
        for _,h in envelopes:
            i=bisect.bisect_left(dp,h)
            if i==len(dp): dp.append(h)
            else: dp[i]=h
        return len(dp)
# Sort by width asc, height desc (prevents using same-width envelopes twice). LIS on height. O(n log n).
# Follow-up: 3D variant (width,height,depth) — NP-hard in general, greedy heuristics.
# Follow-up: Longest Increasing Subsequence (LC 300) — simpler, single dimension.

44.script:
# PHASE 1 — CLARIFY
# "'?' matches any single char. '*' matches any sequence (including empty). Full match. Right?"
# "s='aa',p='a'→false ✓  s='aa',p='*'→true ✓  s='adceb',p='*a*b'→true ✓"
class _44_WildcardMatching_Brute:
    def isMatch(self,s,p):
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i,j):
            if j==len(p): return i==len(s)
            if p[j]=='*': return dp(i,j+1) or (i<len(s) and dp(i+1,j))
            if i<len(s) and (p[j]=='?' or p[j]==s[i]): return dp(i+1,j+1)
            return False
        return dp(0,0)
class _44_WildcardMatching:
    def isMatch(self,s,p):
        m,n=len(s),len(p); dp=[[False]*(n+1) for _ in range(m+1)]
        dp[0][0]=True
        for j in range(1,n+1): dp[0][j]=dp[0][j-1] and p[j-1]=='*'
        for i in range(1,m+1):
            for j in range(1,n+1):
                if p[j-1]=='*': dp[i][j]=dp[i-1][j] or dp[i][j-1]
                elif p[j-1]=='?' or p[j-1]==s[i-1]: dp[i][j]=dp[i-1][j-1]
        return dp[m][n]
# Bottom-up DP. '*' matches empty (dp[i][j-1]) or one more char (dp[i-1][j]). O(mn). Space O(mn).
# Follow-up: Regular Expression Matching (LC 10) — '*' means zero-or-more of preceding char; different.
# Follow-up: O(m+n) space with rolling array — keep only current and previous row.

