# PHASE 1 — CLARIFY
# "Return all ways to segment s into dictionary words. Right?"
# "s='catsanddog',wordDict=['cat','cats','and','sand','dog']→['cats and dog','cat sand dog'] ✓"
class _140_WordBreakII_Brute:
    def wordBreak(self,s,wordDict):
        words=set(wordDict); result=[]
        def bt(start,path):
            if start==len(s): result.append(' '.join(path)); return
            for end in range(start+1,len(s)+1):
                if s[start:end] in words: path.append(s[start:end]); bt(end,path); path.pop()
        bt(0,[]); return result
class _140_WordBreakII:
    def wordBreak(self,s,wordDict):
        from functools import lru_cache
        words=set(wordDict); max_l=max(len(w) for w in words)
        @lru_cache(maxsize=None)
        def dp(start):
            if start==len(s): return ['']
            result=[]
            for end in range(start+1,min(start+max_l,len(s))+1):
                if s[start:end] in words:
                    for rest in dp(end):
                        result.append(s[start:end]+(' '+rest if rest else ''))
            return result
        return dp(0)
# Memoized backtracking: dp(start) = all sentences from s[start:]. O(n²*2^n) worst case. Space O(n*2^n).
# Follow-up: Word Break I (LC 139) — just check existence, DP O(n²).
# Follow-up: if wordDict is a Trie — optimize inner loop to O(max_len) per position.

834.script:
# PHASE 1 — CLARIFY
# "Undirected tree with n nodes. Return sum of distances from each node to all others. Right?"
# "n=6,edges=[[0,1],[0,2],[2,3],[2,4],[2,5]]→[8,12,6,10,10,10] ✓"
class _834_SumOfDistancesInTree_Brute:
    def sumOfDistancesInTree(self,n,edges):
        from collections import defaultdict,deque
        graph=defaultdict(list)
        for u,v in edges: graph[u].append(v); graph[v].append(u)
        def bfs(src):
            dist=[0]*n; visited={src}; q=deque([(src,0)])
            while q:
                node,d=q.popleft()
                for nb in graph[node]:
                    if nb not in visited: visited.add(nb); dist[nb]=d+1; q.append((nb,d+1))
            return sum(dist)
        return [bfs(i) for i in range(n)]
class _834_SumOfDistancesInTree:
    def sumOfDistancesInTree(self,n,edges):
        from collections import defaultdict
        graph=defaultdict(list)
        for u,v in edges: graph[u].append(v); graph[v].append(u)
        count=[1]*n; ans=[0]*n
        def dfs1(node,parent):
            for child in graph[node]:
                if child==parent: continue
                dfs1(child,node); count[node]+=count[child]; ans[node]+=ans[child]+count[child]
        def dfs2(node,parent):
            for child in graph[node]:
                if child==parent: continue
                ans[child]=ans[node]-count[child]+(n-count[child]); dfs2(child,node)
        dfs1(0,-1); dfs2(0,-1); return ans
# Two DFS: root sum + rerooting. O(n). Space O(n).
# Follow-up: if tree is weighted — include edge weights in distance calculations.
# Follow-up: find the centroid — node minimizing sum of distances.

