# PHASE 1 — CLARIFY
# "Undirected graph. Find shortest path visiting all nodes. Can revisit nodes. Right?"
# "graph=[[1,2,3],[0],[0],[0]]→4 ✓"
class _847_ShortestPathVisitingAllNodes_Brute:
    def shortestPathLength(self,graph):
        from collections import deque
        n=len(graph); full=(1<<n)-1
        if n==1: return 0
        dist=[[float('inf')]*n for _ in range(1<<n)]
        q=deque()
        for i in range(n): dist[1<<i][i]=0; q.append((1<<i,i,0))
        while q:
            mask,node,d=q.popleft()
            if mask==full: return d
            for nb in graph[node]:
                nmask=mask|(1<<nb)
                if d+1<dist[nmask][nb]: dist[nmask][nb]=d+1; q.append((nmask,nb,d+1))
        return -1
class _847_ShortestPathVisitingAllNodes:
    def shortestPathLength(self,graph):
        from collections import deque
        n=len(graph); full=(1<<n)-1
        if n==1: return 0
        seen=set(); q=deque()
        for i in range(n):
            q.append((1<<i,i,0)); seen.add((1<<i,i))
        while q:
            mask,node,d=q.popleft()
            if mask==full: return d
            for nb in graph[node]:
                nmask=mask|(1<<nb)
                if (nmask,nb) not in seen:
                    seen.add((nmask,nb)); q.append((nmask,nb,d+1))
        return -1
# BFS on (visited_mask, current_node) states. O(2^n * n). Space O(2^n * n).
# Follow-up: if graph is directed — same approach, just directed edges.
# Follow-up: if we need the actual path — track parent state in BFS.

