# PHASE 1 — CLARIFY
# "Knight in dungeon[m][n], starts top-left, ends bottom-right. Must always have >=1 HP.
#  Cells have positive/negative values. Find min initial HP. Right?"
# "dungeon=[[-2,-3,3],[-5,-10,1],[10,30,-5]]→7 ✓"
class _174_DungeonGame_Brute:
    def calculateMinimumHP(self,dungeon):
        m,n=len(dungeon),len(dungeon[0])
        dp=[[0]*n for _ in range(m)]
        dp[m-1][n-1]=max(1,1-dungeon[m-1][n-1])
        for c in range(n-2,-1,-1): dp[m-1][c]=max(1,dp[m-1][c+1]-dungeon[m-1][c])
        for r in range(m-2,-1,-1): dp[r][n-1]=max(1,dp[r+1][n-1]-dungeon[r][n-1])
        for r in range(m-2,-1,-1):
            for c in range(n-2,-1,-1): dp[r][c]=max(1,min(dp[r+1][c],dp[r][c+1])-dungeon[r][c])
        return dp[0][0]
class _174_DungeonGame:
    def calculateMinimumHP(self,dungeon):
        m,n=len(dungeon),len(dungeon[0])
        dp=[[float('inf')]*(n+1) for _ in range(m+1)]
        dp[m][n-1]=dp[m-1][n]=1
        for r in range(m-1,-1,-1):
            for c in range(n-1,-1,-1):
                need=min(dp[r+1][c],dp[r][c+1])-dungeon[r][c]
                dp[r][c]=max(need,1)
        return dp[0][0]
# Bottom-up from destination: min HP needed to survive from each cell. O(mn). Space O(mn) or O(n).
# Follow-up: if knight can also move up/left — more complex DP with cycles (Bellman-Ford).
