# PHASE 1 — CLARIFY
# "At most k transactions. Maximize profit. Right?"
# "k=2,prices=[3,2,6,5,0,3]→7 ✓"
class _188_StockIV_Brute:
    def maxProfit(self,k,prices):
        n=len(prices)
        if k>=n//2:
            return sum(max(0,prices[i+1]-prices[i]) for i in range(n-1))
        dp=[[0]*n for _ in range(k+1)]
        for t in range(1,k+1):
            max_so_far=float('-inf')
            for d in range(1,n):
                max_so_far=max(max_so_far,dp[t-1][d-1]-prices[d-1])
                dp[t][d]=max(dp[t][d-1],max_so_far+prices[d])
        return dp[k][n-1]
class _188_StockIV:
    def maxProfit(self,k,prices):
        n=len(prices)
        if k>=n//2: return sum(max(0,b-a) for a,b in zip(prices,prices[1:]))
        buy=[-float('inf')]*k; sell=[0]*k
        for p in prices:
            for i in range(k):
                buy[i]=max(buy[i],(sell[i-1] if i>0 else 0)-p)
                sell[i]=max(sell[i],buy[i]+p)
        return sell[-1]
# k states for buy/sell. O(nk). Space O(k).
# Follow-up: Best Time III (LC 123) — k=2 special case.
# Follow-up: unlimited transactions (LC 122) — sum all positive price differences.

