# PHASE 1 — CLARIFY
# "Find maximum number of points that lie on the same straight line. Right?"
# "points=[[1,1],[2,2],[3,3]]→3 ✓  points=[[1,1],[3,2],[5,3],[4,1],[2,3],[1,4]]→4 ✓"
class _149_MaxPointsOnALine_Brute:
    def maxPoints(self,points):
        from math import gcd; n=len(points)
        if n<=2: return n
        best=2
        for i in range(n):
            slopes={}
            for j in range(i+1,n):
                dx=points[j][0]-points[i][0]; dy=points[j][1]-points[i][1]
                g=gcd(abs(dx),abs(dy)) if (dx or dy) else 1
                if g: dx//=g; dy//=g
                if dx<0 or (dx==0 and dy<0): dx,dy=-dx,-dy
                slopes[(dx,dy)]=slopes.get((dx,dy),1)+1
                best=max(best,slopes[(dx,dy)])
        return best
class _149_MaxPointsOnALine:
    def maxPoints(self,points):
        from math import gcd; n=len(points)
        if n<=2: return n; best=2
        for i in range(n):
            cnt={}
            for j in range(i+1,n):
                dx=points[j][0]-points[i][0]; dy=points[j][1]-points[i][1]
                g=gcd(abs(dx),abs(dy)) if dx or dy else 1
                dx//=g; dy//=g
                if dx<0 or (dx==0 and dy<0): dx,dy=-dx,-dy
                cnt[(dx,dy)]=cnt.get((dx,dy),1)+1; best=max(best,cnt[(dx,dy)])
