    def _update(self,r,c,delta):
        i=r
        while i<=self.m:
            j=c
            while j<=self.n: self.bit[i][j]+=delta; j+=j&(-j)
            i+=i&(-i)
    def _query(self,r,c):
        s=0; i=r
        while i>0:
            j=c
            while j>0: s+=self.bit[i][j]; j-=j&(-j)
            i-=i&(-i)
        return s
    def update(self,r,c,val): self._update(r+1,c+1,val-self.mat[r][c]); self.mat[r][c]=val
    def sumRegion(self,r1,c1,r2,c2): return self._query(r2+1,c2+1)-self._query(r1,c2+1)-self._query(r2+1,c1)+self._query(r1,c1)
