# "Minimize transactions to settle debts between friends. Right?"
# "transactions=[[0,1,10],[2,0,5]]→2 ✓"
class _465_OptimalAccountBalancing_Brute:
    def minTransfers(self,transactions):
        from collections import defaultdict
        bal=defaultdict(int)
        for u,v,w in transactions: bal[u]-=w; bal[v]+=w
        debts=[b for b in bal.values() if b!=0]
        def bt(idx):
