    def minTransfers(self,transactions):
        from collections import defaultdict
        bal=defaultdict(int)
        for u,v,w in transactions: bal[u]-=w; bal[v]+=w
        debts=[b for b in bal.values() if b]
        def dfs(i):
            while i<len(debts) and not debts[i]: i+=1
            if i==len(debts): return 0
            res=float('inf')
            for j in range(i+1,len(debts)):
