# PHASE 1 — CLARIFY
# "m×n grid, 3 colors, adjacent cells different. Count ways mod 10^9+7. Right?"
# "m=1,n=1→3 ✓  m=1,n=2→6 ✓  m=5,n=5→580986"
class _1931_PaintingGridWithThreeDifferentColors_Brute:
    def colorTheGrid(self,m,n):
        MOD=10**9+7
        # Generate valid column patterns
        def valid_col(mask,m):
            colors=[]
            for _ in range(m): colors.append(mask%3); mask//=3
            return all(colors[i]!=colors[i+1] for i in range(m-1))
        def compatible(c1,c2,m):
            a,b=c1,c2
            for _ in range(m):
                if a%3==b%3: return False
                a//=3; b//=3
            return True
        cols=[c for c in range(3**m) if valid_col(c,m)]
        dp={c:1 for c in cols}
        for _ in range(n-1):
            ndp={c:0 for c in cols}
            for c1 in cols:
                for c2 in cols:
                    if compatible(c1,c2,m): ndp[c2]=(ndp[c2]+dp[c1])%MOD
            dp=ndp
        return sum(dp.values())%MOD
class _1931_PaintingGridWithThreeDifferentColors:
    def colorTheGrid(self,m,n):
        MOD=10**9+7
        from itertools import product
        def valid(col): return all(col[i]!=col[i+1] for i in range(m-1))
        def compat(c1,c2): return all(c1[i]!=c2[i] for i in range(m))
        cols=[c for c in product(range(3),repeat=m) if valid(c)]
        dp={c:1 for c in cols}
        for _ in range(n-1):
            ndp={c:0 for c in cols}
            for c1 in cols:
                if not dp[c1]: continue
                for c2 in cols:
                    if compat(c1,c2): ndp[c2]=(ndp[c2]+dp[c1])%MOD
            dp=ndp
        return sum(dp.values())%MOD
# Column-by-column DP with valid column patterns. O(n * 3^m * 3^m) = O(n * 9^m). Space O(3^m).
# Follow-up: if 4 colors allowed — same approach, patterns grow to 4^m.
# Follow-up: Number of Ways to Paint N×3 Grid (LC 1411) — closed-form formula for m=3.

