        return sum(grid[i][j]*(xs[i+1]-xs[i])*(ys[j+1]-ys[j]) for i in range(len(xs)-1) for j in range(len(ys)-1) if grid[i][j])%MOD
class _850_RectangleAreaII:
    def rectangleArea(self,rectangles):
        MOD=10**9+7
        xs=sorted(set(x for r in rectangles for x in [r[0],r[2]]))
        xi={x:i for i,x in enumerate(xs)}
        n=len(xs); seg=[0]*n
        events=[]
        for x1,y1,x2,y2 in rectangles: events+=[(y1,1,x1,x2),(y2,-1,x1,x2)]
        events.sort(); result=0; prev_y=0
        def calc():
            covered=0; on=0
            for i in range(n-1):
                if seg[i]: covered+=xs[i+1]-xs[i]
            return covered
        for y,typ,x1,x2 in events:
