# "Grid with teleporters: from some cells you can teleport to another for a cost.
#  Find minimum cost path from (0,0) to (m-1,n-1). Right?"
class _3651_MinCostPathTeleportations_Brute:
    def minCost(self,grid,teleporters):
        import heapq
        m,n=len(grid),len(grid[0])
        dist=[[float('inf')]*n for _ in range(m)]; dist[0][0]=0
        tp={} 
        for r1,c1,r2,c2,cost in teleporters: tp.setdefault((r1,c1),[]).append((r2,c2,cost))
        heap=[(0,0,0)]
        while heap:
            d,r,c=heapq.heappop(heap)
            if d>dist[r][c]: continue
            if r==m-1 and c==n-1: return d
            for dr,dc in [(0,1),(1,0)]:
