# PHASE 1 — CLARIFY
# "Count pairs (i,j) where i<j and nums1[i]-nums1[j]<=nums2[i]-nums2[j]. Right?"
# "nums1=[3,2,5],nums2=[2,2,1]→3 ✓"
class _2426_NumberOfPairsSatisfyingInequality_Brute:
    def numberOfPairs(self,nums1,nums2):
        count=0; n=len(nums1)
        for i in range(n):
            for j in range(i+1,n):
                if nums1[i]-nums1[j]<=nums2[i]-nums2[j]: count+=1
        return count
class _2426_NumberOfPairsSatisfyingInequality:
    def numberOfPairs(self,nums1,nums2):
        import bisect
        diff=[a-b for a,b in zip(nums1,nums2)]; count=0; sorted_so_far=[]
        for d in diff:
            count+=bisect.bisect_right(sorted_so_far,d)
            bisect.insort(sorted_so_far,d)
        return count
# Rearrange: nums1[i]-nums2[i] <= nums1[j]-nums2[j]. Count inversions in diff array. O(n log n).
# Follow-up: Count of Smaller Numbers After Self (LC 315) — count elements smaller to the right.
# Follow-up: if inequality is strict (<) — change bisect_right to bisect_left.

