class _3161_BlockPlacementQueries_Brute:
    def getResults(self,queries):
        obstacles=sorted([0]); result=[]; n=max(q[1] for q in queries)+1
        for q in queries:
            if q[0]==1: obstacles=sorted(obstacles+[q[1]])
            else:
                x,sz=q[1],q[2]
                # Find max gap to the left of x
                import bisect; idx=bisect.bisect_right(obstacles,x)-1
                gap=obstacles[idx+1 if idx+1<len(obstacles) and obstacles[idx+1]<=x else idx]-obstacles[max(0,idx-1)] if False else 0
                # Simpler: find max gap between consecutive obstacles up to x
                obs_left=[o for o in obstacles if o<=x]
                max_gap=max(obs_left[i+1]-obs_left[i] for i in range(len(obs_left)-1)) if len(obs_left)>1 else obs_left[0]
                result.append(max_gap>=sz)
        return result
