# "Find longest subarray where sum of odds = sum of evens. Right?"
class _3721_LongestBalancedSubarrayII_Brute:
    def longestBalancedSubarray(self,nums):
        n=len(nums); best=0
        for i in range(n):
            odd=even=0
            for j in range(i,n):
                if nums[j]%2: odd+=nums[j]
                else: even+=nums[j]
                if odd==even: best=max(best,j-i+1)
        return best
class _3721_LongestBalancedSubarrayII:
    def longestBalancedSubarray(self,nums):
        # prefix (odd_sum - even_sum); find longest subarray with diff=0
        diff_map={0:-1}; prefix=0; best=0
        for i,v in enumerate(nums):
            prefix+=v if v%2 else -v
            if prefix in diff_map: best=max(best,i-diff_map[prefix])
            else: diff_map[prefix]=i
        return best
